<!doctype html>
<html lang="vi">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{{ config('app.name', 'Sổ Tay') }} · Blog</title>
<style>
:root{--ink:#15241f;--muted:#697772;--paper:#f5f4ee;--white:#fff;--green:#174c3b;--lime:#d8ec77;--line:#e4e7df;--orange:#ed8053;--shadow:0 12px 40px #1c332014}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer}a{color:inherit;text-decoration:none}.shell{max-width:1180px;margin:auto;padding:0 24px}.nav{height:76px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{font-size:24px;font-weight:850;letter-spacing:-1.5px;color:var(--green)}.brand span{color:var(--orange)}.nav-actions{display:flex;gap:10px;align-items:center}.btn{border:0;background:var(--green);color:white;padding:11px 17px;border-radius:10px;font-weight:700}.btn.secondary{background:white;color:var(--ink);border:1px solid var(--line)}.btn.lime{background:var(--lime);color:var(--ink)}.btn.small{padding:7px 11px;font-size:14px}.hero{padding:64px 0 48px;display:grid;grid-template-columns:1.4fr .6fr;gap:34px;align-items:end}.eyebrow{color:var(--green);text-transform:uppercase;letter-spacing:2px;font-weight:800;font-size:12px}.hero h1{font-size:clamp(42px,7vw,76px);line-height:.99;letter-spacing:-4px;max-width:760px;margin:14px 0 22px}.hero h1 em{font-family:Georgia,serif;color:var(--orange);font-weight:500}.hero p{color:var(--muted);max-width:580px;font-size:18px}.hero-note{background:var(--lime);padding:24px;border-radius:18px;transform:rotate(1deg)}.hero-note strong{font-family:Georgia,serif;font-size:28px;line-height:1.2;display:block}.hero-note span{display:block;margin-top:14px;color:#41552e}.toolbar{display:flex;gap:12px;margin:10px 0 22px}.search{flex:1;min-width:180px}.field{border:1px solid var(--line);background:white;padding:12px 14px;border-radius:10px;width:100%;outline-color:#77a582}.chips{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:28px}.chip{border:1px solid var(--line);border-radius:999px;padding:7px 13px;background:transparent;color:var(--muted)}.chip.active,.chip:hover{background:var(--green);color:white;border-color:var(--green)}.layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:28px}.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.section-head h2{font-size:24px;letter-spacing:-.6px;margin:0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{background:white;border-radius:16px;overflow:hidden;box-shadow:var(--shadow);border:1px solid #eceee8;display:flex;flex-direction:column}.cover{height:180px;background:linear-gradient(135deg,#d8ec77,#a5c3ad);display:flex;align-items:center;justify-content:center;color:#174c3b;font-size:34px;overflow:hidden}.cover img{width:100%;height:100%;object-fit:cover}.card-body{padding:18px;display:flex;flex-direction:column;flex:1}.tag{font-size:12px;font-weight:750;color:#47715d;text-transform:uppercase;letter-spacing:.8px}.card h3{margin:9px 0;font-size:21px;line-height:1.2;letter-spacing:-.5px}.excerpt{color:var(--muted);margin:0 0 15px}.meta{color:var(--muted);font-size:13px;margin-top:auto}.card-foot{display:flex;gap:8px;margin-top:14px}.side{display:flex;flex-direction:column;gap:16px}.panel{background:white;border:1px solid var(--line);border-radius:16px;padding:20px}.panel h3{margin:0 0 8px}.panel p{color:var(--muted);margin:0 0 14px}.panel form{display:flex;flex-direction:column;gap:9px}.panel .btn{width:100%}.taglist{display:flex;gap:8px;flex-wrap:wrap}.footer{padding:50px 0 35px;color:var(--muted);font-size:13px}.empty{background:white;border:1px dashed var(--line);border-radius:16px;padding:30px;color:var(--muted);grid-column:1/-1}.modal{position:fixed;inset:0;background:#0a1e18a8;display:none;align-items:center;justify-content:center;padding:20px;z-index:20}.modal.open{display:flex}.dialog{background:var(--paper);border-radius:20px;max-width:760px;width:100%;max-height:90vh;overflow:auto;padding:24px;box-shadow:0 25px 90px #0004}.dialog.wide{max-width:920px}.dialog-head{display:flex;justify-content:space-between;align-items:center}.dialog h2{font-size:32px;line-height:1.1;margin:12px 0}.close{border:0;background:white;border-radius:50%;width:38px;height:38px;font-size:20px}.article{white-space:pre-wrap;color:#34423c;font-size:17px}.auth-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.form-stack{display:flex;flex-direction:column;gap:10px}.form-stack label{font-weight:700;font-size:14px}.form-stack input,.form-stack textarea,.form-stack select{width:100%;margin-top:4px}.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:#142b22;color:white;padding:12px 18px;border-radius:12px;z-index:50;display:none;box-shadow:var(--shadow)}.toast.show{display:block}.comment{padding:12px 0;border-bottom:1px solid var(--line)}.comment small{color:var(--muted)}.hide{display:none!important}
@media(max-width:800px){.hero{grid-template-columns:1fr;padding-top:42px}.hero-note{display:none}.layout{grid-template-columns:1fr}.side{display:grid;grid-template-columns:1fr 1fr}.hero h1{letter-spacing:-2.5px}}@media(max-width:560px){.shell{padding:0 15px}.nav{height:64px}.nav-actions .desktop{display:none}.hero{padding:35px 0}.hero h1{font-size:48px}.toolbar{flex-direction:column}.grid,.side,.auth-grid{grid-template-columns:1fr}.cover{height:160px}.dialog{padding:18px}}
</style>
</head>
<body>
<header class="shell nav">
  <a class="brand" href="/">SỔ TAY<span>.</span></a>
  <div class="nav-actions">
    <button class="btn secondary small desktop hide" id="myPostsBtn" onclick="showMyPosts()">Bài của tôi</button><button class="btn secondary small desktop hide" id="profileBtn" onclick="showProfile()">Hồ sơ</button><button class="btn secondary small desktop" onclick="showBookmarks()">Bài đã lưu</button>
    <button class="btn secondary small desktop" onclick="showNotifications()">Thông báo</button><button class="btn secondary small desktop hide" id="adminBtn" onclick="showAdmin()">Quản trị</button>
    <button class="btn lime small desktop hide" id="writeBtn" onclick="openWriter()">Viết bài</button>
    <button class="btn small" id="authBtn" onclick="openAuth()">Đăng nhập</button>
  </div>
</header>
<main class="shell">
  <section class="hero">
    <div><div class="eyebrow">Góc đọc · Góc viết</div><h1>Ý tưởng hay<br>đáng được <em>chia sẻ.</em></h1><p>Nơi mọi người kể chuyện, lưu điều hữu ích và tìm thấy những góc nhìn mới mỗi ngày.</p></div>
    <div class="hero-note"><strong>“Viết để hiểu.<br>Đọc để mở rộng.”</strong><span>Một cộng đồng dành cho sự tò mò.</span></div>
  </section>
  <div class="toolbar"><input id="search" class="field search" placeholder="Tìm bài viết, chủ đề..." onkeydown="if(event.key==='Enter')loadPosts()"><select id="category" class="field" style="max-width:220px" onchange="loadPosts()"><option value="">Tất cả danh mục</option></select><button class="btn" onclick="loadPosts()">Tìm kiếm</button></div>
  <div id="tagchips" class="chips"></div>
  <div class="layout">
    <section><div class="section-head"><h2 id="listTitle">Bài viết mới</h2><button class="btn secondary small" onclick="loadPosts()">Làm mới</button></div><div id="posts" class="grid"><div class="empty">Đang tải bài viết...</div></div></section>
    <aside class="side">
      <div class="panel"><h3>Nhận bài mới qua email</h3><p>Đăng ký nhận thông báo khi có bài viết mới.</p><form onsubmit="subscribe(event)"><input class="field" id="newsletterEmail" type="email" required placeholder="Email của bạn"><button class="btn lime">Đăng ký nhận tin</button></form></div>
      <div class="panel"><h3>Thẻ phổ biến</h3><p>Chọn một chủ đề để lọc bài.</p><div id="taglist" class="taglist"><span class="meta">Đang tải...</span></div></div>
      <div id="accountPanel" class="panel"><h3>Cùng tham gia</h3><p>Tạo tài khoản để theo dõi tác giả, lưu bài và chia sẻ kiến thức của bạn.</p><button class="btn" onclick="openAuth('register')">Tạo tài khoản</button></div>
    </aside>
  </div>
  <footer class="footer">SỔ TAY · Blog chia sẻ kiến thức · Laravel API</footer>
</main>

<div class="modal" id="authModal"><div class="dialog"><div class="dialog-head"><span class="eyebrow">Tài khoản</span><button class="close" onclick="closeModal('authModal')">×</button></div><button type="button" class="btn secondary" style="width:100%;margin:18px 0" onclick="location.href='/auth/github'">Tiếp tục với GitHub</button><div class="auth-grid"><form class="form-stack" onsubmit="login(event)"><h2>Đăng nhập</h2><label>Email<input class="field" type="email" name="email" required></label><label>Mật khẩu<input class="field" type="password" name="password" required></label><button class="btn">Đăng nhập</button><button type="button" class="btn secondary" onclick="forgotPassword()">Quên mật khẩu?</button></form><form class="form-stack" onsubmit="register(event)"><h2>Tạo tài khoản</h2><label>Tên hiển thị<input class="field" name="userName" required maxlength="255"></label><label>Email<input class="field" type="email" name="email" required></label><label>Mật khẩu<input class="field" type="password" name="password" required minlength="8"></label><button class="btn lime">Đăng ký</button><small>Email xác minh sẽ được gửi theo cấu hình máy chủ.</small></form></div></div></div>
<div class="modal" id="articleModal"><div class="dialog wide"><div class="dialog-head"><span id="articleCategory" class="eyebrow"></span><button class="close" onclick="closeModal('articleModal')">×</button></div><h2 id="articleTitle"></h2><div class="meta" id="articleMeta"></div><div class="card-foot"><button class="btn secondary small" id="articleLike"></button><button class="btn secondary small" id="articleBookmark"></button><button class="btn secondary small" id="followBtn"></button></div><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><div id="articleContent" class="article"></div><h3>Bình luận</h3><div id="comments"></div><form class="form-stack" onsubmit="comment(event)"><textarea class="field" id="commentText" rows="3" placeholder="Viết bình luận..." required></textarea><button class="btn small" style="align-self:flex-start">Gửi bình luận</button></form></div></div>
<div class="modal" id="writerModal"><div class="dialog wide"><div class="dialog-head"><span class="eyebrow">Góc sáng tác</span><button class="close" onclick="closeModal('writerModal')">×</button></div><h2>Viết bài mới</h2><form id="writerForm" class="form-stack" onsubmit="publishPost(event)"><label>Tiêu đề<input class="field" name="title" required maxlength="500"></label><label>Danh mục<select class="field" name="categoryId" id="writerCategory" required></select></label><label>Tóm tắt<input class="field" name="excerpt" maxlength="2000"></label><label>Nội dung<textarea class="field" name="content" rows="9" required></textarea></label><div class="auth-grid"><label>Tags, cách nhau bằng dấu phẩy<input class="field" name="tags" placeholder="laravel, công nghệ"></label><label>Ảnh bìa URL (hoặc tải lên)<input class="field" name="coverImage" placeholder="https://..."></label></div><label>Thời điểm đăng<input class="field" name="scheduledAt" type="datetime-local"></label><label>SEO description<input class="field" name="metaDescription" maxlength="320"></label><div class="auth-grid"><label>Tải ảnh bìa<input class="field" type="file" id="coverFile" accept="image/*"></label><label>Trạng thái<select class="field" name="status"><option value="Draft">Lưu nháp</option><option value="Pending">Gửi duyệt</option><option value="Scheduled">Lên lịch</option><option value="Published">Xuất bản ngay (quản trị viên)</option></select></label></div><button class="btn">Lưu bài viết</button></form></div></div>
<div class="modal" id="genericModal"><div class="dialog"><div class="dialog-head"><span class="eyebrow" id="genericKicker"></span><button class="close" onclick="closeModal('genericModal')">×</button></div><h2 id="genericTitle"></h2><div id="genericBody"></div></div></div>
<div id="toast" class="toast"></div>
<script>
const API='/api/v1';
let token=localStorage.getItem('blog_access')||'';
let refresh=localStorage.getItem('blog_refresh')||'';
let currentUser=JSON.parse(localStorage.getItem('blog_user')||'null');
let currentPost=null,editingPostId=null,activeTag='',categories=[];
async function api(path,options={},retry=true){
  const headers=Object.assign({'Accept':'application/json'},options.headers||{});
  if(token)headers.Authorization='Bearer '+token;
  if(options.body && !(options.body instanceof FormData))headers['Content-Type']='application/json';
  let response=await fetch(API+path,Object.assign({},options,{headers:headers}));
  let body={};try{body=await response.json()}catch(e){}
  if(response.status===401&&refresh&&retry){
    try{let r=await fetch(API+'/auth/refresh',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({refresh_token:refresh})});let b=await r.json();if(r.ok&&b.data){saveSession(b.data);return api(path,options,false)}}catch(e){}
    logout(false);
  }
  if(!response.ok)throw new Error(body.message||'Có lỗi khi gửi yêu cầu.');
  return body.data;
}
function saveSession(data){token=data.access_token;refresh=data.refresh_token;currentUser=data.user;localStorage.setItem('blog_access',token);localStorage.setItem('blog_refresh',refresh);localStorage.setItem('blog_user',JSON.stringify(currentUser));updateAuth()}
function updateAuth(){document.getElementById('authBtn').textContent=currentUser?'Xin chào, '+currentUser.userName:'Đăng nhập';document.getElementById('writeBtn').classList.toggle('hide',!currentUser);document.getElementById('profileBtn').classList.toggle('hide',!currentUser);document.getElementById('myPostsBtn').classList.toggle('hide',!currentUser);document.getElementById('adminBtn').classList.toggle('hide',currentUser?.role!=='Admin');document.getElementById('accountPanel').innerHTML=currentUser?'<h3>'+esc(currentUser.userName)+'</h3><p>'+esc(currentUser.email)+'</p><button class="btn secondary" onclick="requestVerification()">Gửi lại email xác minh</button><button class="btn" style="margin-top:8px" onclick="logout()">Đăng xuất</button>':'<h3>Cùng tham gia</h3><p>Tạo tài khoản để theo dõi tác giả, lưu bài và chia sẻ kiến thức của bạn.</p><button class="btn" onclick="openAuth(\'register\')">Tạo tài khoản</button>'}
function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){let t=document.getElementById('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3300)}
function openAuth(tab){document.getElementById('authModal').classList.add('open')}
function closeModal(id){document.getElementById(id).classList.remove('open')}
async function loadCategories(){try{categories=await api('/categories');if(!Array.isArray(categories))categories=categories.data||[];let options='<option value="">Tất cả danh mục</option>';let writer='';categories.forEach(c=>{options+='<option value="'+c.id+'">'+esc(c.name)+'</option>';writer+='<option value="'+c.id+'">'+esc(c.name)+'</option>'});document.getElementById('category').innerHTML=options;document.getElementById('writerCategory').innerHTML=writer}catch(e){toast(e.message)}}
async function loadTags(){try{let data=await api('/tags?limit=30');let list=data.data||data;let html='';(list.data||list).forEach(t=>{html+='<button class="chip '+(activeTag===t.slug?'active':'')+'" onclick="filterTag(\''+esc(t.slug)+'\')">'+esc(t.name)+'</button>'});document.getElementById('tagchips').innerHTML=html;document.getElementById('taglist').innerHTML=html||'<span class="meta">Chưa có thẻ.</span>'}catch(e){}}
function filterTag(tag){activeTag=activeTag===tag?'':tag;loadTags();loadPosts()}
async function loadPosts(){let p=new URLSearchParams({limit:'30'});let key=document.getElementById('search').value.trim();let cat=document.getElementById('category').value;if(key)p.set('keyword',key);if(cat)p.set('categoryId',cat);if(activeTag)p.set('tag',activeTag);document.getElementById('listTitle').textContent=activeTag?'Chủ đề: '+activeTag:'Bài viết mới';try{let result=await api('/posts?'+p.toString());let rows=result.posts||[];let html=rows.map(post=>'<article class="card"><div class="cover">'+(post.coverImage?'<img src="'+esc(post.coverImage)+'" alt="">':'✦')+'</div><div class="card-body"><div class="tag">'+esc(post.category?.name||'Bài viết')+'</div><h3>'+esc(post.title)+'</h3><p class="excerpt">'+esc(post.excerpt||'')+'</p><div class="meta">Bởi <a href="#" onclick="showAuthor(\''+encodeURIComponent(post.authorName||'')+'\');return false">'+esc(post.authorName||'Tác giả')+'</a> · '+date(post.publishedAt)+' · '+(post.viewCount||0)+' lượt đọc</div><div class="card-foot"><button class="btn small" onclick="openPost('+post.id+')">Đọc bài</button><button class="btn secondary small" onclick="quickLike('+post.id+',this)">♡ '+(post.likesCount||0)+'</button></div></div></article>').join('');document.getElementById('posts').innerHTML=html||'<div class="empty">Chưa có bài viết phù hợp. Hãy thử từ khóa khác hoặc tạo bài đầu tiên.</div>'}catch(e){document.getElementById('posts').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
function openResetForm(){let qs=new URLSearchParams(location.search);document.getElementById('genericKicker').textContent='Tài khoản';document.getElementById('genericTitle').textContent='Đặt lại mật khẩu';document.getElementById('genericBody').innerHTML='<form class="form-stack" onsubmit="submitReset(event)"><input type="hidden" id="resetToken" value="'+esc(qs.get('token')||'')+'"><input type="hidden" id="resetEmail" value="'+esc(qs.get('email')||'')+'"><label>Mật khẩu mới<input class="field" id="resetPassword" type="password" minlength="8" required></label><label>Nhập lại mật khẩu<input class="field" id="resetPasswordConfirm" type="password" minlength="8" required></label><button class="btn">Cập nhật mật khẩu</button></form>';document.getElementById('genericModal').classList.add('open')}
async function submitReset(e){e.preventDefault();try{await api('/auth/password/reset',{method:'POST',body:JSON.stringify({token:document.getElementById('resetToken').value,email:document.getElementById('resetEmail').value,password:document.getElementById('resetPassword').value,password_confirmation:document.getElementById('resetPasswordConfirm').value})});closeModal('genericModal');history.replaceState({},'', '/');toast('Đã đổi mật khẩu. Bạn có thể đăng nhập.')}catch(err){toast(err.message)}}function date(v){if(!v)return '';return new Date(v).toLocaleDateString('vi-VN')}
async function openPost(id){try{currentPost=await api('/posts/'+id);await api('/posts/'+id+'/view',{method:'POST'});document.getElementById('articleCategory').textContent=currentPost.category?.name||'Bài viết';document.getElementById('articleTitle').textContent=currentPost.title;document.getElementById('articleMeta').textContent='Tác giả: '+(currentPost.authorName||'')+' · '+date(currentPost.publishedAt)+' · '+(currentPost.viewCount||0)+' lượt đọc';document.getElementById('articleContent').textContent=currentPost.content||'';document.getElementById('articleLike').textContent='♡ Thích · '+(currentPost.likesCount||0);document.getElementById('articleBookmark').textContent='☆ Lưu bài';document.getElementById('followBtn').textContent='Theo dõi '+(currentPost.authorName||'tác giả');document.getElementById('articleLike').onclick=()=>toggleLike(currentPost.id);document.getElementById('articleBookmark').onclick=()=>toggleBookmark(currentPost.id);document.getElementById('followBtn').onclick=()=>follow(currentPost.authorId);await loadComments();document.getElementById('articleModal').classList.add('open')}catch(e){toast(e.message)}}
async function loadComments(){try{let comments=await api('/posts/'+currentPost.id+'/comments');document.getElementById('comments').innerHTML=(comments||[]).map(c=>'<div class="comment"><strong>'+esc(c.userName)+'</strong><div>'+esc(c.content)+'</div><small>'+date(c.createdAt)+'</small></div>').join('')||'<p class="meta">Chưa có bình luận được duyệt.</p>'}catch(e){}}
async function comment(e){e.preventDefault();if(!token)return openAuth();try{await api('/posts/'+currentPost.id+'/comments',{method:'POST',body:JSON.stringify({content:document.getElementById('commentText').value})});document.getElementById('commentText').value='';toast('Bình luận đã gửi và đang chờ duyệt.')}catch(err){toast(err.message)}}
async function quickLike(id,button){if(!token)return openAuth();try{let r=await api('/posts/'+id+'/likes',{method:'POST'});button.textContent='♥ '+r.likesCount}catch(e){toast(e.message)}}
async function toggleLike(id){if(!token)return openAuth();try{let r=await api('/posts/'+id+'/likes',{method:'POST'});document.getElementById('articleLike').textContent='♥ Thích · '+r.likesCount}catch(e){toast(e.message)}}
async function toggleBookmark(id){if(!token)return openAuth();try{await api('/posts/'+id+'/bookmark',{method:'PUT'});toast('Đã lưu bài viết.')}catch(e){toast(e.message)}}
async function follow(id){if(!token)return openAuth();try{await api('/authors/'+id+'/follow',{method:'POST'});toast('Đã theo dõi tác giả.')}catch(e){toast(e.message)}}
async function subscribe(e){e.preventDefault();try{await api('/newsletter/subscribe',{method:'POST',body:JSON.stringify({email:document.getElementById('newsletterEmail').value})});toast('Hãy kiểm tra hộp thư để xác nhận đăng ký.')}catch(err){toast(err.message)}}
async function login(e){e.preventDefault();let f=new FormData(e.target);try{saveSession(await api('/auth/login',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})}));closeModal('authModal');toast('Đăng nhập thành công.')}catch(err){toast(err.message)}}
async function register(e){e.preventDefault();let f=new FormData(e.target);try{await api('/auth/register',{method:'POST',body:JSON.stringify({userName:f.get('userName'),email:f.get('email'),password:f.get('password')})});toast('Đăng ký thành công. Hãy đăng nhập và xác minh email.')}catch(err){toast(err.message)}}
async function forgotPassword(){let email=prompt('Nhập email để nhận liên kết đặt lại mật khẩu:');if(!email)return;try{await api('/auth/password/forgot',{method:'POST',body:JSON.stringify({email})});toast('Nếu email tồn tại, liên kết đặt lại đã được gửi.')}catch(e){toast(e.message)}}
async function requestVerification(){try{await api('/auth/email/verification-notification',{method:'POST'});toast('Đã gửi email xác minh.')}catch(e){toast(e.message)}}
function logout(show=true){token='';refresh='';currentUser=null;['blog_access','blog_refresh','blog_user'].forEach(k=>localStorage.removeItem(k));updateAuth();if(show)toast('Đã đăng xuất.')}
function openWriter(){if(!token)return openAuth();editingPostId=null;document.getElementById('writerForm').reset();document.querySelector('#writerModal h2').textContent='Viết bài mới';document.getElementById('writerModal').classList.add('open')}
async function showMyPosts(){if(!token)return openAuth();try{let result=await api('/posts/me?limit=50');let rows=result.data||[];document.getElementById('genericKicker').textContent='Góc viết';document.getElementById('genericTitle').textContent='Bài viết của tôi';document.getElementById('genericBody').innerHTML=rows.map(p=>'<div class="comment"><strong>'+esc(p.title)+'</strong><div class="meta">'+esc(p.status)+' · '+date(p.updatedAt)+'</div><button class="btn secondary small" onclick="editPost('+p.id+')">Chỉnh sửa</button></div>').join('')||'<p>Bạn chưa viết bài nào.</p>';document.getElementById('genericModal').classList.add('open')}catch(e){toast(e.message)}}
async function editPost(id){try{let p=await api('/posts/'+id+'/manage');editingPostId=id;let f=document.getElementById('writerForm');f.elements.title.value=p.title;f.elements.categoryId.value=p.categoryId;f.elements.excerpt.value=p.excerpt||'';f.elements.content.value=p.content||'';f.elements.tags.value=(p.tags||[]).map(t=>t.name).join(', ');f.elements.coverImage.value=p.coverImage||'';f.elements.metaDescription.value=p.metaDescription||'';f.elements.status.value=(p.status||'draft').charAt(0).toUpperCase()+(p.status||'draft').slice(1);if(p.scheduledAt)f.elements.scheduledAt.value=new Date(p.scheduledAt).toISOString().slice(0,16);document.querySelector('#writerModal h2').textContent='Chỉnh sửa bài viết';closeModal('genericModal');document.getElementById('writerModal').classList.add('open')}catch(e){toast(e.message)}}
async function publishPost(e){e.preventDefault();let f=new FormData(e.target);let cover=f.get('coverImage');let file=document.getElementById('coverFile').files[0];if(file){try{let fd=new FormData();fd.append('image',file);let uploaded=await api('/media',{method:'POST',body:fd});cover=uploaded.url}catch(err){toast('Tải ảnh lỗi: '+err.message);return}}let scheduled=f.get('scheduledAt');let data={title:f.get('title'),categoryId:Number(f.get('categoryId')),excerpt:f.get('excerpt'),content:f.get('content'),coverImage:cover||null,tags:(f.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean),status:f.get('status'),metaDescription:f.get('metaDescription')||null};if(scheduled)data.scheduledAt=new Date(scheduled).toISOString();if(data.status==='Scheduled'&&!scheduled){toast('Chọn thời điểm đăng bài.');return}try{await api(editingPostId?'/posts/'+editingPostId:'/posts',{method:editingPostId?'PUT':'POST',body:JSON.stringify(data)});editingPostId=null;closeModal('writerModal');e.target.reset();toast('Đã lưu bài. Nếu không phải quản trị viên, bài đăng sẽ chờ duyệt.');loadPosts()}catch(err){toast(err.message)}}
async function showAuthor(username){try{let result=await api('/authors/'+encodeURIComponent(username));let a=result.author;let rows=result.posts?.data||[];document.getElementById('genericKicker').textContent='Tác giả';document.getElementById('genericTitle').textContent=a.username;document.getElementById('genericBody').innerHTML='<p>'+esc(a.bio||'Chưa có giới thiệu.')+'</p><p class="meta">'+a.followersCount+' người theo dõi · '+a.postsCount+' bài viết</p>'+(currentUser?'<button class="btn small" onclick="follow('+a.id+')">Theo dõi tác giả</button>':'')+'<h3>Bài viết</h3>'+rows.map(p=>'<div class="comment"><a href="#" onclick="closeModal(\'genericModal\');openPost('+p.id+');return false"><strong>'+esc(p.title)+'</strong></a><div class="meta">'+date(p.published_at)+'</div></div>').join('');document.getElementById('genericModal').classList.add('open')}catch(e){toast(e.message)}}
async function showAdmin(){if(!currentUser||currentUser.role!=='Admin')return;try{let stats=await api('/admin/reports');let queue=await api('/admin/posts?status=pending&limit=50');let comments=await api('/admin/comments?status=Pending&limit=30');let commentRows=comments.data?.data||[];let summary='<div class="auth-grid"><div class="panel"><strong>'+stats.totalViews+'</strong><div class="meta">Lượt đọc</div></div><div class="panel"><strong>'+stats.publishedPosts+'</strong><div class="meta">Bài đã đăng</div></div><div class="panel"><strong>'+stats.activeUsers+'</strong><div class="meta">Tài khoản hoạt động</div></div><div class="panel"><strong>'+stats.engagementRate+'%</strong><div class="meta">Tương tác</div></div></div>';let postsHtml=queue.posts.map(p=>'<div class="comment"><strong>'+esc(p.title)+'</strong><div class="meta">'+esc(p.authorName||'')+' · '+esc(p.status)+'</div><button class="btn small" onclick="approvePost('+p.id+')">Duyệt / xuất bản</button></div>').join('')||'<p>Không có bài chờ duyệt.</p>';let commentsHtml=commentRows.map(c=>'<div class="comment"><strong>'+esc(c.user?.username||'Người dùng')+'</strong><div>'+esc(c.content)+'</div><small>'+esc(c.post?.title||'')+'</small><br><button class="btn small" onclick="approveComment('+c.id+')">Duyệt bình luận</button></div>').join('')||'<p>Không có bình luận chờ duyệt.</p>';document.getElementById('genericKicker').textContent='Quản trị';document.getElementById('genericTitle').textContent='Tổng quan và kiểm duyệt';document.getElementById('genericBody').innerHTML=summary+'<h3>Bài chờ duyệt</h3>'+postsHtml+'<h3>Bình luận chờ duyệt</h3>'+commentsHtml;document.getElementById('genericModal').classList.add('open')}catch(e){toast(e.message)}}
async function approveComment(id){try{await api('/comments/'+id+'/approve',{method:'POST'});toast('Đã duyệt bình luận.');showAdmin()}catch(e){toast(e.message)}}async function approvePost(id){try{await api('/posts/'+id+'/approve',{method:'POST'});toast('Đã duyệt bài.');showAdmin()}catch(e){toast(e.message)}}async function showProfile(){if(!token)return openAuth();try{let u=await api('/profile');document.getElementById('genericKicker').textContent='Tài khoản';document.getElementById('genericTitle').textContent='Hồ sơ của bạn';document.getElementById('genericBody').innerHTML='<form class="form-stack" onsubmit="saveProfile(event)"><label>Tên hiển thị<input class="field" name="userName" value="'+esc(u.userName)+'" required></label><label>Email<input class="field" type="email" name="email" value="'+esc(u.email)+'" required></label><label>Ảnh đại diện URL<input class="field" name="avatarUrl" value="'+esc(u.avatarUrl||'')+'"></label><label>Giới thiệu<textarea class="field" name="bio" rows="3">'+esc(u.bio||'')+'</textarea></label><button class="btn">Lưu hồ sơ</button></form><hr><form class="form-stack" onsubmit="changePassword(event)"><h3>Đổi mật khẩu</h3><label>Mật khẩu hiện tại<input class="field" name="currentPassword" type="password" required></label><label>Mật khẩu mới<input class="field" name="newPassword" type="password" minlength="8" required></label><button class="btn secondary">Đổi mật khẩu</button></form>';document.getElementById('genericModal').classList.add('open')}catch(e){toast(e.message)}}
async function saveProfile(e){e.preventDefault();let f=new FormData(e.target);try{let u=await api('/profile',{method:'PUT',body:JSON.stringify({userName:f.get('userName'),email:f.get('email'),avatarUrl:f.get('avatarUrl')||null,bio:f.get('bio')})});currentUser=u;localStorage.setItem('blog_user',JSON.stringify(u));updateAuth();toast('Đã lưu hồ sơ. Nếu đổi email, hãy xác minh email mới.')}catch(err){toast(err.message)}}
async function changePassword(e){e.preventDefault();let f=new FormData(e.target);try{await api('/profile/password',{method:'PUT',body:JSON.stringify({currentPassword:f.get('currentPassword'),newPassword:f.get('newPassword')})});e.target.reset();toast('Đã đổi mật khẩu.')}catch(err){toast(err.message)}}async function showBookmarks(){if(!token)return openAuth();try{let r=await api('/bookmarks');let rows=r.data||[];document.getElementById('genericKicker').textContent='Thư viện cá nhân';document.getElementById('genericTitle').textContent='Bài viết đã lưu';document.getElementById('genericBody').innerHTML=rows.map(p=>'<div class="comment"><a href="#" onclick="closeModal(\'genericModal\');openPost('+p.id+');return false"><strong>'+esc(p.title)+'</strong></a><div class="meta">'+esc(p.author?.username||'')+'</div></div>').join('')||'<p>Chưa lưu bài viết nào.</p>';document.getElementById('genericModal').classList.add('open')}catch(e){toast(e.message)}}
async function showNotifications(){if(!token)return openAuth();try{let r=await api('/notifications');document.getElementById('genericKicker').textContent='Cập nhật';document.getElementById('genericTitle').textContent='Thông báo ('+(r.unreadCount||0)+' chưa đọc)';let rows=r.notifications?.data||[];document.getElementById('genericBody').innerHTML=rows.map(n=>'<div class="comment">'+esc(n.data?.title||'Hoạt động mới')+'<div class="meta">'+date(n.created_at)+'</div></div>').join('')||'<p>Chưa có thông báo.</p>';document.getElementById('genericModal').classList.add('open')}catch(e){toast(e.message)}}
document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('open')}));
updateAuth();loadCategories().then(()=>loadPosts());loadTags();if(location.pathname==='/reset-password')openResetForm();let oauth=new URLSearchParams(location.search).get('oauth');if(oauth){toast('Đăng nhập GitHub chưa hoàn tất: '+oauth);history.replaceState({},'', '/');}
</script>
</body>
</html>